INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6182751, 912552, 119419, '<td valign="top">Has potential, pity about the tourist, but they add a personal touch. Beautiful monument</td>', 'Has potential, pity about the tourist, but they add a personal touch. Beautiful monument', '2010-10-06 04:27:51.000000', NULL, 1),
(6182756, 912977, 119419, '<td valign="top">Good composition idea, would like more of the building included if it was possible because the foreground is a little heavy</td>', 'Good composition idea, would like more of the building included if it was possible because the foreground is a little heavy', '2010-10-06 04:32:52.000000', NULL, 1),
(6182758, 913064, 119419, '<td valign="top">lovely tone effect in the lighting gives the frame character</td>', 'lovely tone effect in the lighting gives the frame character', '2010-10-06 04:34:00.000000', NULL, 1),
(6182761, 913109, 119419, '<td valign="top">beautiful light setting, probably would have used a little more fill on the upper torso, maybe just my monitor</td>', 'beautiful light setting, probably would have used a little more fill on the upper torso, maybe just my monitor', '2010-10-06 04:36:06.000000', NULL, 1),
(6182780, 912642, 61084, '<td valign="top">I researched this bike and Heather online. You did a great job capturing the solemn, almost desolate and eerie feel to this ghost bike monument and the processing definitely helps here. Well done. I do question some of the composition choices though as the horizon is dead center and  I would also normally like to have a little more room on the right side of the frame so the bike wasn''t so closed in. Then again I''m a little on the fence there because I think it being a little jammed up against the right part of the frame helps give it that off kilter "somethings wrong here" feel which sadly fits the situation with the death of a 42 year old woman. Terrible loss, but you do her memory justice with your photo.<br/> <br/>Back to the horizon line. I feel a slightly different angle would have made this even more effective. You angle of view places the bike seat at the horizon and blocks some of the mountains in the background. I would have liked to have seen an unobstructed view of that great shrub/tree above the handle bars. With that said...the photo is about the bike and I''m still giving you a 9 because it''s a truly compelling image despite the MINOR compositional preferences I''ve listed. Good luck!</td>', 'I researched this bike and Heather online. You did a great job capturing the solemn, almost desolate and eerie feel to this ghost bike monument and the processing definitely helps here. Well done. I do question some of the composition choices though as the horizon is dead center and  I would also normally like to have a little more room on the right side of the frame so the bike wasn''t so closed in. Then again I''m a little on the fence there because I think it being a little jammed up against the right part of the frame helps give it that off kilter "somethings wrong here" feel which sadly fits the situation with the death of a 42 year old woman. Terrible loss, but you do her memory justice with your photo. Back to the horizon line. I feel a slightly different angle would have made this even more effective. You angle of view places the bike seat at the horizon and blocks some of the mountains in the background. I would have liked to have seen an unobstructed view of that great shrub/tree above the handle bars. With that said...the photo is about the bike and I''m still giving you a 9 because it''s a truly compelling image despite the MINOR compositional preferences I''ve listed. Good luck!', '2010-10-06 05:12:58.000000', NULL, 1),
(6182839, 913034, 106806, '<td valign="top">Don''t know if you will see this comment since I''m not voting in this round (to avoid the temptation of voting low) ... but this image is really well done - the fact it isn''t B&amp;W seems to pull me out of my desk and into the grave yard I feel open and cold ...</td>', 'Don''t know if you will see this comment since I''m not voting in this round (to avoid the temptation of voting low) ... but this image is really well done - the fact it isn''t B&W seems to pull me out of my desk and into the grave yard I feel open and cold ...', '2010-10-06 07:29:26.000000', NULL, 1),
(6182908, 913049, 114233, '<td valign="top">I was just about to comment on the man in the picture above the statue and how it ruined the shot... then I realised the symbolism of it. A man of Colour at the Voortrekker Monument! Nicely spotted!<br/> <br/>Strong comp with a central statue. Would like to have seen a bit more of the sky and maybe increased the blue saturation. Otherwise very sharp and clear!</td>', 'I was just about to comment on the man in the picture above the statue and how it ruined the shot... then I realised the symbolism of it. A man of Colour at the Voortrekker Monument! Nicely spotted! Strong comp with a central statue. Would like to have seen a bit more of the sky and maybe increased the blue saturation. Otherwise very sharp and clear!', '2010-10-06 09:03:13.000000', NULL, 1),
(6183173, 913134, 33672, '<td valign="top">Nice! I wonder where this is</td>', 'Nice! I wonder where this is', '2010-10-06 11:49:50.000000', NULL, 1),
(6183192, 913089, 120507, '<td valign="top">I love this. I may of cropped it to remove the tree line on the right hand side and then crop the left to recenter the monument.</td>', 'I love this. I may of cropped it to remove the tree line on the right hand side and then crop the left to recenter the monument.', '2010-10-06 12:08:06.000000', NULL, 1),
(6183201, 913013, 110041, '<td valign="top">Shame about the main subjects all being in the shade and also the cable running across the photo. otherwise a nice composition as your eyes are drawn up from the fountain to the top of the spire.</td>', 'Shame about the main subjects all being in the shade and also the cable running across the photo. otherwise a nice composition as your eyes are drawn up from the fountain to the top of the spire.', '2010-10-06 12:12:33.000000', NULL, 1),
(6183202, 913108, 110041, '<td valign="top">Can someone check the horse for steroids, please?</td>', 'Can someone check the horse for steroids, please?', '2010-10-06 12:13:38.000000', NULL, 1),
(6183206, 912987, 110041, '<td valign="top">looks pretty fuzzy.</td>', 'looks pretty fuzzy.', '2010-10-06 12:16:09.000000', NULL, 1),
(6183212, 912434, 110041, '<td valign="top">I can''t decide whether or not the underexposed foreground needs to be there. I think something should be there to maintain the aspect of the shot, but the concrete pavement detracts.</td>', 'I can''t decide whether or not the underexposed foreground needs to be there. I think something should be there to maintain the aspect of the shot, but the concrete pavement detracts.', '2010-10-06 12:17:40.000000', NULL, 1),
(6183246, 913082, 48588, '<td valign="top">I like your idea, but would have liked to see more light on the face.  Perhaps if shot from the other side, it would have also put more emphasis on the guitar?  My eye is drawn more to the cloak than anything that is particularly "Stevie."</td>', 'I like your idea, but would have liked to see more light on the face.  Perhaps if shot from the other side, it would have also put more emphasis on the guitar?  My eye is drawn more to the cloak than anything that is particularly "Stevie."', '2010-10-06 12:35:11.000000', NULL, 1),
(6183253, 912739, 48588, '<td valign="top">Ah all right!  This was the first thing I thought of when I saw this challenge, but I''m living in NYC now.  One of my favorite statues, glad to see it in the challenge!</td>', 'Ah all right!  This was the first thing I thought of when I saw this challenge, but I''m living in NYC now.  One of my favorite statues, glad to see it in the challenge!', '2010-10-06 12:39:39.000000', NULL, 1),
(6183267, 913033, 48588, '<td valign="top">Shooting at a different time such that the sky wasn''t blown out I think would have added another layer to this image.</td>', 'Shooting at a different time such that the sky wasn''t blown out I think would have added another layer to this image.', '2010-10-06 12:47:35.000000', NULL, 1),
(6183270, 912529, 48588, '<td valign="top">I would have liked for the point where the arch meets to have not been cut off.  My eye follows it as part of the frame.  Still, a nice shot!</td>', 'I would have liked for the point where the arch meets to have not been cut off.  My eye follows it as part of the frame.  Still, a nice shot!', '2010-10-06 12:49:35.000000', NULL, 1),
(6183303, 912881, 32145, '<td valign="top">Nice contrast in the image. The border distracts though.</td>', 'Nice contrast in the image. The border distracts though.', '2010-10-06 13:18:34.000000', NULL, 1),
(6183309, 912210, 32145, '<td valign="top">Careful what you upload. I assume you didn''t intend for the photo to be rotated and stretched??</td>', 'Careful what you upload. I assume you didn''t intend for the photo to be rotated and stretched??', '2010-10-06 13:21:53.000000', NULL, 1),
(6183354, 912781, 119747, '<td valign="top">Great photo, amazing reflection! 10</td>', 'Great photo, amazing reflection! 10', '2010-10-06 13:47:13.000000', NULL, 1),
(6183402, 912986, 46020, '<td valign="top">Beautiful picture, however, I fear that some may think it doesn''t fit the challenge but I do!  Good luck!</td>', 'Beautiful picture, however, I fear that some may think it doesn''t fit the challenge but I do!  Good luck!', '2010-10-06 14:27:08.000000', NULL, 1),
(6183523, 912881, 40391, '<td valign="top">Nice perspective, converted well to B&amp;W with the image popping nicely and the clouds provide a good background.  However, the border adds nothing but is really distracting to me.  I do like this shot and it gets a 7 from me.</td>', 'Nice perspective, converted well to B&W with the image popping nicely and the clouds provide a good background.  However, the border adds nothing but is really distracting to me.  I do like this shot and it gets a 7 from me.', '2010-10-06 16:01:43.000000', NULL, 1),
(6183545, 912781, 40391, '<td valign="top">This is my favorite for the challenge and my only 10.The lighting, colours, perspective and clarity are fantastic.  Judging by the lens flare on the street lamps and the smoothness of the water, I''m guessing at least a 30sec exposure (probably way off).  To maintain the exposure I''m also guessing some sort of filtering was used. Please let me know as I would love to try and achieve something like this myself one day.  Well Done!</td>', 'This is my favorite for the challenge and my only 10.The lighting, colours, perspective and clarity are fantastic.  Judging by the lens flare on the street lamps and the smoothness of the water, I''m guessing at least a 30sec exposure (probably way off).  To maintain the exposure I''m also guessing some sort of filtering was used. Please let me know as I would love to try and achieve something like this myself one day.  Well Done!', '2010-10-06 16:11:29.000000', NULL, 1),
(6183584, 913125, 121916, '<td valign="top">The rim of light around the monument distracts somewhat from this otherwise lovely image.</td>', 'The rim of light around the monument distracts somewhat from this otherwise lovely image.', '2010-10-06 16:37:51.000000', NULL, 1),
(6183589, 912456, 121082, '<td valign="top">Very moving Photo. Nice job</td>', 'Very moving Photo. Nice job', '2010-10-06 16:42:13.000000', NULL, 1),
(6183590, 913123, 121082, '<td valign="top">Very nice Photo. Great job</td>', 'Very nice Photo. Great job', '2010-10-06 16:42:26.000000', NULL, 1),
(6183591, 912926, 121082, '<td valign="top">Nice Photo. Good job</td>', 'Nice Photo. Good job', '2010-10-06 16:43:01.000000', NULL, 1),
(6183592, 913082, 121082, '<td valign="top">Loved SRV. Didnt know this existed. Great job.</td>', 'Loved SRV. Didnt know this existed. Great job.', '2010-10-06 16:43:31.000000', NULL, 1),
(6183593, 912574, 121082, '<td valign="top">Wow what a spectacular Photo. My fav.</td>', 'Wow what a spectacular Photo. My fav.', '2010-10-06 16:43:46.000000', NULL, 1),
(6183656, 912781, 96881, '<td valign="top">I don''t know what this is, but it does look really interesting.  Reflections here are great which makes this one of the standouts in this challenge.  Colour is also very interesting as well, which helps to make it interesting.  The centred composition maybe is not great, but I note that to the right is nothing to help (but does border the image well......)<br/>Not exactly what I was expecting from this challenge, but it is well done and the results are great.<br/>Great time to photograph it, and great reflections.........Well done.</td>', 'I don''t know what this is, but it does look really interesting.  Reflections here are great which makes this one of the standouts in this challenge.  Colour is also very interesting as well, which helps to make it interesting.  The centred composition maybe is not great, but I note that to the right is nothing to help (but does border the image well......)Not exactly what I was expecting from this challenge, but it is well done and the results are great.Great time to photograph it, and great reflections.........Well done.', '2010-10-06 17:17:40.000000', NULL, 1),
(6183664, 912642, 96881, '<td valign="top">Great subject........something different and thats a good thing.  The processing you have done on this does work really well, but maybe a little darker (make the bike stand out a little more against the scrub) could have worked.<br/>The crop and angle though is interesting, and I wonder why you chose it.  I understand that you wish to keep the road in the image (and I would as well) but moving around a little more (to the right if possible) could have improved this.........The crop is way too close to the edge of the bike, so moving around could have kept the road in the image, and the bike away from the image edge........also, a lower view could have made the bike larger against the rest of the photo, really emphasising the bike, making it large..........<br/>But still, one of the better images in the challenge, an interesting subject and some good processing</td>', 'Great subject........something different and thats a good thing.  The processing you have done on this does work really well, but maybe a little darker (make the bike stand out a little more against the scrub) could have worked.The crop and angle though is interesting, and I wonder why you chose it.  I understand that you wish to keep the road in the image (and I would as well) but moving around a little more (to the right if possible) could have improved this.........The crop is way too close to the edge of the bike, so moving around could have kept the road in the image, and the bike away from the image edge........also, a lower view could have made the bike larger against the rest of the photo, really emphasising the bike, making it large..........But still, one of the better images in the challenge, an interesting subject and some good processing', '2010-10-06 17:25:34.000000', NULL, 1),
(6183673, 913063, 96881, '<td valign="top">The colour through this is great.  The reds through the bricks against the blue does contrast well, and the statue does stand out well against the sky.........The angle does ensure that his name is also a main part of the image, which helps us identify him, rather than it being just another horse statue.<br/>Colour noise though is apparent in the upper area of the image which needs some attention.  The image is very centered and the crop is pretty tight.<br/>But a good image and amoung the better entries I have seen.</td>', 'The colour through this is great.  The reds through the bricks against the blue does contrast well, and the statue does stand out well against the sky.........The angle does ensure that his name is also a main part of the image, which helps us identify him, rather than it being just another horse statue.Colour noise though is apparent in the upper area of the image which needs some attention.  The image is very centered and the crop is pretty tight.But a good image and amoung the better entries I have seen.', '2010-10-06 17:28:59.000000', NULL, 1),
(6183685, 913134, 96881, '<td valign="top">Interesting monument, but there are a lot of distractions around it.  Don''t know what else is there, but maybe a different angle, combined with a tighter crop might have worked and removed the distraction elements.  I wonder if almost lying on the ground near the base and photographing upwards, showing the fingers reaching for the sky might have made for a really interesting image......and something different...........</td>', 'Interesting monument, but there are a lot of distractions around it.  Don''t know what else is there, but maybe a different angle, combined with a tighter crop might have worked and removed the distraction elements.  I wonder if almost lying on the ground near the base and photographing upwards, showing the fingers reaching for the sky might have made for a really interesting image......and something different...........', '2010-10-06 17:35:50.000000', NULL, 1),
(6183691, 912319, 96881, '<td valign="top">Nice monument........great colours, great day to be out there photographing.<br/>But, why did you photograph this side of the monument........a stronger image could have been from a different angle, getting the faces if possible.......Also wondering why you did not wait until the marches had moved away.  They don''t seem to be adding anything, cause they are too small, so just form a distraction.  The crop is very tight at the top near the flag as well.</td>', 'Nice monument........great colours, great day to be out there photographing.But, why did you photograph this side of the monument........a stronger image could have been from a different angle, getting the faces if possible.......Also wondering why you did not wait until the marches had moved away.  They don''t seem to be adding anything, cause they are too small, so just form a distraction.  The crop is very tight at the top near the flag as well.', '2010-10-06 17:38:46.000000', NULL, 1),
(6183694, 912821, 96881, '<td valign="top">Yep, Natural Monument, slight stretch but I will let it slide........not exactly what the challenge was after but likely to do well.<br/>Reflections are great which help the image.  Some work on the colours could have helped as the reds and greens could have really made this image stand out.</td>', 'Yep, Natural Monument, slight stretch but I will let it slide........not exactly what the challenge was after but likely to do well.Reflections are great which help the image.  Some work on the colours could have helped as the reds and greens could have really made this image stand out.', '2010-10-06 17:41:19.000000', NULL, 1),
(6183697, 913125, 96881, '<td valign="top">Depth of field is great here......really works well and makes the image.  Pink is nice and makes the image stand out.  Haloing though around the monument though does hurt the image.<br/>Use of the rule of thirds does also work really well here with the monument placement.  The border does finish off the image quite well also.</td>', 'Depth of field is great here......really works well and makes the image.  Pink is nice and makes the image stand out.  Haloing though around the monument though does hurt the image.Use of the rule of thirds does also work really well here with the monument placement.  The border does finish off the image quite well also.', '2010-10-06 17:43:17.000000', NULL, 1),
(6183701, 913059, 96881, '<td valign="top">Lack of focus really hurts this image.  not getting the crop or angle of the image either......cutting off the left name does not work, and covering up the other makes no sense to me........</td>', 'Lack of focus really hurts this image.  not getting the crop or angle of the image either......cutting off the left name does not work, and covering up the other makes no sense to me........', '2010-10-06 17:45:54.000000', NULL, 1),
(6183713, 913057, 113419, '<td valign="top">this needs to be straightened</td>', 'this needs to be straightened', '2010-10-06 17:51:18.000000', NULL, 1),
(6183716, 912881, 113419, '<td valign="top">very nicely done - and your boarder adds just the right touch</td>', 'very nicely done - and your boarder adds just the right touch', '2010-10-06 17:53:16.000000', NULL, 1),
(6183719, 913123, 96881, '<td valign="top">First impressions, processing is overdone, straight on, centered composition............<br/> <br/>But, looking deeper, there is an attempt to create something, maybe even to make a statement, to capture something that is different from the rest......maybe even to portray the wastefulness of war, the senseless loss of human life, the overall loss..........<br/> <br/>Don''t know what you did to the central gravestone, but I hope it is legal, but I fear it might not be........but I will vote as if it is.......<br/> <br/>I now really like the processing, the statement, the image.....one of the best in the challenge.  I do wonder if the crop could have been at the edge of the outside stones (cut the back ones if need be, not the front)..........<br/> <br/>But hey, a good image..........well done for producing something both different, and one that works.</td>', 'First impressions, processing is overdone, straight on, centered composition............ But, looking deeper, there is an attempt to create something, maybe even to make a statement, to capture something that is different from the rest......maybe even to portray the wastefulness of war, the senseless loss of human life, the overall loss.......... Don''t know what you did to the central gravestone, but I hope it is legal, but I fear it might not be........but I will vote as if it is....... I now really like the processing, the statement, the image.....one of the best in the challenge.  I do wonder if the crop could have been at the edge of the outside stones (cut the back ones if need be, not the front).......... But hey, a good image..........well done for producing something both different, and one that works.', '2010-10-06 17:53:53.000000', NULL, 1),
(6183724, 912543, 113419, '<td valign="top">very different pov - I like it</td>', 'very different pov - I like it', '2010-10-06 17:54:41.000000', NULL, 1),
(6183725, 913089, 113419, '<td valign="top">you captured some nice sky colors although a bit noisy</td>', 'you captured some nice sky colors although a bit noisy', '2010-10-06 17:55:30.000000', NULL, 1),
(6183727, 913089, 96881, '<td valign="top">Great colours, interesting Silhouette produced as a result.  Colour noise though is a problem in the image, and the centered composition isn''t great.  I think someone else took a picture of the same memorial</td>', 'Great colours, interesting Silhouette produced as a result.  Colour noise though is a problem in the image, and the centered composition isn''t great.  I think someone else took a picture of the same memorial', '2010-10-06 17:56:32.000000', NULL, 1),
(6183731, 913151, 113419, '<td valign="top">very nice abstract here</td>', 'very nice abstract here', '2010-10-06 17:57:54.000000', NULL, 1),
(6183732, 913034, 113419, '<td valign="top">NICE!</td>', 'NICE!', '2010-10-06 17:58:38.000000', NULL, 1),
(6183734, 913108, 113419, '<td valign="top">well done!</td>', 'well done!', '2010-10-06 17:59:37.000000', NULL, 1),
(6183735, 912456, 96881, '<td valign="top">a great place for the challenge, but I am not sure the angle and composition of the image has really used it well.......the tree is just a problem, a black blob in the middle of the image.  There is no focal point in the image, the stones at the front are cropped.  Focus in on one stone, and have the rest stretching in the distance.......remind us that even though the numbers were huge, each were a person, and each individually should be remembered.........</td>', 'a great place for the challenge, but I am not sure the angle and composition of the image has really used it well.......the tree is just a problem, a black blob in the middle of the image.  There is no focal point in the image, the stones at the front are cropped.  Focus in on one stone, and have the rest stretching in the distance.......remind us that even though the numbers were huge, each were a person, and each individually should be remembered.........', '2010-10-06 17:59:45.000000', NULL, 1),
(6183739, 913123, 113419, '<td valign="top">WOW - very nice work!</td>', 'WOW - very nice work!', '2010-10-06 18:01:05.000000', NULL, 1),
(6183740, 912781, 113419, '<td valign="top">Lovely!  Wonderful job with this - the full reflection is amazing.  I understand it''s basic and so cloning out the sticks in the water isn''t allowed (not knocking points for that btw) but I hope you do have a copy where you''ve done that and are planning to print and hang this.  :-)</td>', 'Lovely!  Wonderful job with this - the full reflection is amazing.  I understand it''s basic and so cloning out the sticks in the water isn''t allowed (not knocking points for that btw) but I hope you do have a copy where you''ve done that and are planning to print and hang this.  :-)', '2010-10-06 18:01:07.000000', NULL, 1),
(6183741, 913082, 113419, '<td valign="top">MAN I LOVE STEVIE!!!!!  You''ve done a good job with this photo, my only suggestion would be a bit of light on the face - good black and white - nice job</td>', 'MAN I LOVE STEVIE!!!!!  You''ve done a good job with this photo, my only suggestion would be a bit of light on the face - good black and white - nice job', '2010-10-06 18:01:09.000000', NULL, 1),
(6183747, 912494, 113419, '<td valign="top">this one is nice!  good work - nice capture of light and shadow - beautiful dof</td>', 'this one is nice!  good work - nice capture of light and shadow - beautiful dof', '2010-10-06 18:03:06.000000', NULL, 1),
(6183748, 912987, 113419, '<td valign="top">this is somewhat oof</td>', 'this is somewhat oof', '2010-10-06 18:03:48.000000', NULL, 1),
(6183753, 912037, 113419, '<td valign="top">VERY NICE!  WONDERFUL POV</td>', 'VERY NICE!  WONDERFUL POV', '2010-10-06 18:04:32.000000', NULL, 1),
(6183756, 913125, 113419, '<td valign="top">I like this - I even like the halo around the monument</td>', 'I like this - I even like the halo around the monument', '2010-10-06 18:06:25.000000', NULL, 1),
(6183761, 912977, 96881, '<td valign="top">Interesting........usually called the Shrine of Remembrance though, and never really heard anyone call it the ANZAC Shrine.............<br/>The steps though are a bit dark though, and the curve annoys me, but the lighting on the Shrine is great.  I would have had less steps and more shrine, less dark area and more of the subject, but this composition may  have worked if there was a little more detail in the steps.......</td>', 'Interesting........usually called the Shrine of Remembrance though, and never really heard anyone call it the ANZAC Shrine.............The steps though are a bit dark though, and the curve annoys me, but the lighting on the Shrine is great.  I would have had less steps and more shrine, less dark area and more of the subject, but this composition may  have worked if there was a little more detail in the steps.......', '2010-10-06 18:09:18.000000', NULL, 1),
(6183770, 913024, 96881, '<td valign="top">Yep, grave, taken from in front.....I don''t see the statement, I don''t see the appeal....not sure what you are trying to say.  Maybe something more in the title could help us understand your motivation.....<br/>Technically, its in focus, its centered, but not sure its level<br/>Sorry, but I do not understand why, and there is not a lot of appeal</td>', 'Yep, grave, taken from in front.....I don''t see the statement, I don''t see the appeal....not sure what you are trying to say.  Maybe something more in the title could help us understand your motivation.....Technically, its in focus, its centered, but not sure its levelSorry, but I do not understand why, and there is not a lot of appeal', '2010-10-06 18:14:03.000000', NULL, 1),
(6183776, 912210, 96881, '<td valign="top">A kiwi........I will not hold that against you   :)     (Sorry, had to)<br/> <br/>First, why is the image smaller than allowed.....There is guidance in the forums as to how to maximize the size allowances. It would have helped<br/> <br/>Colours are nice, but the crop is tight.<br/> <br/>I note you have straightened based on the flagpole, but as a result of the wide angle, the monument is at an angle.   It does hurt the image, and is made even more obvious by the partially cropped wall to the right.  Being further away, and showing us more of the monument would have helped.........</td>', 'A kiwi........I will not hold that against you   :)     (Sorry, had to) First, why is the image smaller than allowed.....There is guidance in the forums as to how to maximize the size allowances. It would have helped Colours are nice, but the crop is tight. I note you have straightened based on the flagpole, but as a result of the wide angle, the monument is at an angle.   It does hurt the image, and is made even more obvious by the partially cropped wall to the right.  Being further away, and showing us more of the monument would have helped.........', '2010-10-06 18:17:51.000000', NULL, 1),
(6183782, 913031, 96881, '<td valign="top">The image is well too small........need to use the full available size.<br/>Centered composition.....not a lot of appeal</td>', 'The image is well too small........need to use the full available size.Centered composition.....not a lot of appeal', '2010-10-06 18:23:58.000000', NULL, 1),
