(6185997, 912881, 103411, '<td valign="top">Not sure what others will think of it, but I really like the border you used</td>', 'Not sure what others will think of it, but I really like the border you used', '2010-10-08 09:12:50.000000', NULL, 1),
(6186228, 913013, 114225, '<td valign="top">Nice serenity to this photo. Too bad it''s basic editing, because if you could have cloned the wire out of there, I think this shot would be much improved.</td>', 'Nice serenity to this photo. Too bad it''s basic editing, because if you could have cloned the wire out of there, I think this shot would be much improved.', '2010-10-08 12:49:59.000000', NULL, 1),
(6186230, 913023, 114225, '<td valign="top">Interesting idea for this challenge. I like the idea of a dark silhouette, but I don''t like all the noise in this shot.</td>', 'Interesting idea for this challenge. I like the idea of a dark silhouette, but I don''t like all the noise in this shot.', '2010-10-08 12:50:36.000000', NULL, 1),
(6186232, 913147, 114225, '<td valign="top">Nice perspective and use of black and white. I like how you captured the erosion, as that adds to the interest.</td>', 'Nice perspective and use of black and white. I like how you captured the erosion, as that adds to the interest.', '2010-10-08 12:51:31.000000', NULL, 1),
(6186234, 913089, 114225, '<td valign="top">I do like this overall. Good colors in the sky to indicate riding off in the sunset. I do wish there was a bit less noise, and I''m not super fond of the tree on the right.</td>', 'I do like this overall. Good colors in the sky to indicate riding off in the sunset. I do wish there was a bit less noise, and I''m not super fond of the tree on the right.', '2010-10-08 12:52:34.000000', NULL, 1),
(6186236, 913063, 114225, '<td valign="top">Good low perspective to make it look like the monument is even taller than it is. Nice job keeping any distracting elements out of the background.</td>', 'Good low perspective to make it look like the monument is even taller than it is. Nice job keeping any distracting elements out of the background.', '2010-10-08 12:53:20.000000', NULL, 1),
(6186237, 912881, 114225, '<td valign="top">I like this. Good choice on the close crop and the B&amp;W. Those things help to bring out the details. Most of the time I don''t mind a border, but in this case I feel like it''s actually detracting from the image.</td>', 'I like this. Good choice on the close crop and the B&W. Those things help to bring out the details. Most of the time I don''t mind a border, but in this case I feel like it''s actually detracting from the image.', '2010-10-08 12:54:09.000000', NULL, 1),
(6186238, 913136, 114225, '<td valign="top">Great capture for this challenge. I always stop and read these benches as I come across them.</td>', 'Great capture for this challenge. I always stop and read these benches as I come across them.', '2010-10-08 12:54:36.000000', NULL, 1),
(6186239, 912475, 114225, '<td valign="top">Great job getting low and in the monument for a much more emotive photo.</td>', 'Great job getting low and in the monument for a much more emotive photo.', '2010-10-08 12:55:00.000000', NULL, 1),
(6186240, 912560, 114225, '<td valign="top">I like the perspective and crop used here, I think it adds to the interest. However, I dislike how there is a high key feel to much of it, seems like we are missing out on some crucial details.</td>', 'I like the perspective and crop used here, I think it adds to the interest. However, I dislike how there is a high key feel to much of it, seems like we are missing out on some crucial details.', '2010-10-08 12:55:53.000000', NULL, 1),
