(6186613, 912977, 114225, '<td valign="top">Great colors in this photo. I don''t really care for the amount of negative space at the bottom.</td>', 'Great colors in this photo. I don''t really care for the amount of negative space at the bottom.', '2010-10-08 21:01:10.000000', NULL, 1),
(6186614, 913151, 114225, '<td valign="top">Interesting effect. Definitely gives a sense of ethereal to the statue. Unfortunately the very much blown highlights in the sky and some other places is really distracting to me.</td>', 'Interesting effect. Definitely gives a sense of ethereal to the statue. Unfortunately the very much blown highlights in the sky and some other places is really distracting to me.', '2010-10-08 21:02:32.000000', NULL, 1),
