(6186617, 912543, 114225, '<td valign="top">Nice job using a foreground element to add extra depth to this photo.</td>', 'Nice job using a foreground element to add extra depth to this photo.', '2010-10-08 21:03:48.000000', NULL, 1),
(6186619, 912821, 114225, '<td valign="top">Interesting take on the challenge. I wouldn''t have thought to seek out a natural formations. Good job with the capture as well.</td>', 'Interesting take on the challenge. I wouldn''t have thought to seek out a natural formations. Good job with the capture as well.', '2010-10-08 21:07:54.000000', NULL, 1),
