(6190112, 913108, 3214, '<td valign="top">Congrats to you Barry!  Very nice.</td>', 'Congrats to you Barry!  Very nice.', '2010-10-13 02:05:39.000000', NULL, 0),
(6190118, 912037, 59267, '<td valign="top">Great perspective! congratulations on your ribbon!</td>', 'Great perspective! congratulations on your ribbon!', '2010-10-13 02:11:14.000000', NULL, 0),
(6190119, 912781, 59267, '<td valign="top">Congratulations!</td>', 'Congratulations!', '2010-10-13 02:12:45.000000', NULL, 0),
(6190125, 912037, 65319, '<td valign="top">Oh Ben...Woooo Hoooo!  Congrats on your ribbon!  <br/> <br/>I can hardly "just breathe" as I''m too....<br/> <br/><a href="//www.youtube.com/watch?v=Eg8cDmi7-U8" rel="nofollow" target="_blank">Blinded by the Light</a></td>', 'Oh Ben...Woooo Hoooo!  Congrats on your ribbon!   I can hardly "just breathe" as I''m too.... Blinded by the Light', '2010-10-13 02:15:51.000000', NULL, 0),
(6190147, 912781, 40391, '<td valign="top">Congratulations Anthony on a much deserved win and on your first Blue!<br/> <br/>Thanks for the feedback (got the exposure right at least).  Perhaps if I got rid of my old Rebel and kit lens I might also produce shots like this.  Nah, I think skill plays into it more.  Once again, well done!</td>', 'Congratulations Anthony on a much deserved win and on your first Blue! Thanks for the feedback (got the exposure right at least).  Perhaps if I got rid of my old Rebel and kit lens I might also produce shots like this.  Nah, I think skill plays into it more.  Once again, well done!', '2010-10-13 02:43:59.000000', NULL, 0),
(6190148, 912781, 34659, '<td valign="top">The best shot I''ve ever seen of the arch.  Simply beautiful.  Congratulations!</td>', 'The best shot I''ve ever seen of the arch.  Simply beautiful.  Congratulations!', '2010-10-13 02:44:04.000000', NULL, 0),
(6190149, 912037, 34659, '<td valign="top">Absolutely amazing...  Such a stunning shot.  Perfect balance and emotion.</td>', 'Absolutely amazing...  Such a stunning shot.  Perfect balance and emotion.', '2010-10-13 02:44:43.000000', NULL, 0),
(6190154, 912881, 40391, '<td valign="top">Well done on a top finish!  I''m not surprised to see this do so well.  I am surprised how many comments you got on the border though.  I wonder if that''s a record?</td>', 'Well done on a top finish!  I''m not surprised to see this do so well.  I am surprised how many comments you got on the border though.  I wonder if that''s a record?', '2010-10-13 02:49:28.000000', NULL, 0),
(6190155, 913103, 101702, '<td valign="top">Can''t believe this didn''t finish higher, it was my highest score of the challenge.</td>', 'Can''t believe this didn''t finish higher, it was my highest score of the challenge.', '2010-10-13 02:49:43.000000', NULL, 0),
(6190157, 912781, 109341, '<td valign="top">Well done mate!  Congrats!</td>', 'Well done mate!  Congrats!', '2010-10-13 02:51:47.000000', NULL, 0),
(6190159, 913151, 40391, '<td valign="top">At first I thought this was somehow a water reflection but it didn''t quite make sense.  Either way it really got my attention and was quite appealing to me.  I gave this an 8 and a little surprised it finished as low as it did.  Well done!</td>', 'At first I thought this was somehow a water reflection but it didn''t quite make sense.  Either way it really got my attention and was quite appealing to me.  I gave this an 8 and a little surprised it finished as low as it did.  Well done!', '2010-10-13 02:53:47.000000', NULL, 0),
(6190164, 913108, 28742, '<td valign="top">Way to go, Barry! Congrats!</td>', 'Way to go, Barry! Congrats!', '2010-10-13 02:57:36.000000', NULL, 0),
(6190165, 912037, 30214, '<td valign="top">hey Ben, congrats! excellent shot!</td>', 'hey Ben, congrats! excellent shot!', '2010-10-13 02:58:17.000000', NULL, 0),
