(6190175, 912781, 49819, '<td valign="top">congrats! love the photo (and the monument)</td>', 'congrats! love the photo (and the monument)', '2010-10-13 03:03:20.000000', NULL, 0),
(6190198, 912781, 86218, '<td valign="top">Hey Anthony. Congrats on a very good shot here. Beautifully executed and certainly has made me see this monument (shot to death) in a new light. Ribbon is just a bonus.</td>', 'Hey Anthony. Congrats on a very good shot here. Beautifully executed and certainly has made me see this monument (shot to death) in a new light. Ribbon is just a bonus.', '2010-10-13 03:23:50.000000', NULL, 0),
(6190212, 912781, 50034, '<td valign="top">Excellent visual ring!  Great reflection capture with the Gateway Arch.  Congratulations on your Blue.  :)</td>', 'Excellent visual ring!  Great reflection capture with the Gateway Arch.  Congratulations on your Blue.  :)', '2010-10-13 03:39:16.000000', NULL, 0),
(6190215, 913108, 50034, '<td valign="top">Great Work!  Apparently, he is still Rock-Solid as well as Revered.  :)</td>', 'Great Work!  Apparently, he is still Rock-Solid as well as Revered.  :)', '2010-10-13 03:41:23.000000', NULL, 0),
(6190219, 913123, 50034, '<td valign="top">Congratulations on placement.<br/>Chilling sight in more ways than one.<br/>Hand-over-my-heart gratitude for every sacrifice.</td>', 'Congratulations on placement.Chilling sight in more ways than one.Hand-over-my-heart gratitude for every sacrifice.', '2010-10-13 03:42:50.000000', NULL, 0),
(6190226, 912037, 105130, '<td valign="top">Great stuff Ben, pure art.</td>', 'Great stuff Ben, pure art.', '2010-10-13 03:57:25.000000', NULL, 0),
(6190254, 912977, 30364, '<td valign="top">I voted in this challenge but forgot to comment later.  This was my top pick.  <br/>The memorial rising above a great gulf of darkness was a perfect tribute to our ANZACs and I looked at it for a very long time.  Thoughts turned to the most beautiful tribute to the original ANZACs, by Mustafa Kemal:<br/> <br/><i>Those heroes that shed their blood and lost their lives... <br/>You are now lying in the soil of a friendly country. <br/>Therefore rest in peace.<br/>There is no difference between the Johnnies and Mehmets to us <br/>where they lie side by side here in this country of ours.<br/>You, the mothers, who sent their sons from faraway countries wipe away your tears; <br/>Your sons are now lying in our bosom and are in peace. <br/>After having lost their lives on this land they have become our sons as well.<br/>  - Kemal Atatürk</i> <br/> <br/>Thank you Enzo, for a beautiful and moving photograph.</td>', 'I voted in this challenge but forgot to comment later.  This was my top pick.  The memorial rising above a great gulf of darkness was a perfect tribute to our ANZACs and I looked at it for a very long time.  Thoughts turned to the most beautiful tribute to the original ANZACs, by Mustafa Kemal: Those heroes that shed their blood and lost their lives... You are now lying in the soil of a friendly country. Therefore rest in peace.There is no difference between the Johnnies and Mehmets to us where they lie side by side here in this country of ours.You, the mothers, who sent their sons from faraway countries wipe away your tears; Your sons are now lying in our bosom and are in peace. After having lost their lives on this land they have become our sons as well.  - Kemal Atatürk  Thank you Enzo, for a beautiful and moving photograph.', '2010-10-13 05:06:41.000000', NULL, 0),
(6190258, 912977, 30364, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by love:</b></div><hr/><i> I think this should be cropped - way too much of the bottom area. </i></td></tr></table> <br/> <br/>You can''t blame some people for thinking this.  Presumably they thought the photograph was about the building, while you knew that it was about the meaning of the building.  You won, of course.</td>', 'Originally posted by love: I think this should be cropped - way too much of the bottom area.   You can''t blame some people for thinking this.  Presumably they thought the photograph was about the building, while you knew that it was about the meaning of the building.  You won, of course.', '2010-10-13 05:12:48.000000', NULL, 0),
(6190261, 912781, 102534, '<td valign="top">CONGRATULATIONS!!! Your first Blue Ribbon for a fantastic shot. Keep up the great work!</td>', 'CONGRATULATIONS!!! Your first Blue Ribbon for a fantastic shot. Keep up the great work!', '2010-10-13 05:16:38.000000', NULL, 0),
(6190282, 913059, 49109, '<td valign="top">A posthumous blue? That should make you look for another hobby.<br/>I like the idea of taking a shot of the camera display, though, it gives a nice 70s feel to the image.<br/> <br/>ETA: You might get DQed for this, as it is not possible to say when the original shot was taken.<br/><br/><i>Message edited by author 2010-10-13 05:44:09.</i></td>', 'A posthumous blue? That should make you look for another hobby.I like the idea of taking a shot of the camera display, though, it gives a nice 70s feel to the image. ETA: You might get DQed for this, as it is not possible to say when the original shot was taken.', '2010-10-13 06:42:08.000000', '2010-10-13 06:44:09.000000', 0),
(6190300, 913108, 37529, '<td valign="top">Barry, great shot!  Way to go on the ribbon.</td>', 'Barry, great shot!  Way to go on the ribbon.', '2010-10-13 07:25:36.000000', NULL, 0),
(6190327, 912781, 46314, '<td valign="top">Awesome shot. Great job. Congrats on the well-deserved ribbon.</td>', 'Awesome shot. Great job. Congrats on the well-deserved ribbon.', '2010-10-13 07:55:11.000000', NULL, 0),
(6190328, 913151, 106806, '<td valign="top">hmmmm.... the only artistic interpretation in the whole challenge in my view. Ok lets clarify there are some good shots of monuments but nearly all draw their merit from composition rather than any photogenic treatment .... I like this image the best from the whole bunch ... well ok its fighting with <a href="//www.dpchallenge.com/image.php?IMAGE_ID=912475" rel="nofollow" target="_blank">Kaw Point Stones Reprise</a> <br/> <br/></td>', 'hmmmm.... the only artistic interpretation in the whole challenge in my view. Ok lets clarify there are some good shots of monuments but nearly all draw their merit from composition rather than any photogenic treatment .... I like this image the best from the whole bunch ... well ok its fighting with Kaw Point Stones Reprise  ', '2010-10-13 07:55:32.000000', NULL, 0),
